def find_k_factors(n, k, factors):
    if k == 1:
        if n > 1:
            factors.append(n)
            return True
        return False

    # Try all possible divisors
    for d in range(2, n // 2 + 1):
        if n % d == 0:
            # Try to find k-1 factors of n/d
            if find_k_factors(n // d, k - 1, factors):
                factors.append(d)
                return True

    return False

n, k = map(int, input().split())
factors = []

if find_k_factors(n, k, factors):
    print(' '.join(map(str, factors)))
else:
    print(-1)
