def prime_factors(n):
    factors = []
    i = 2
    while i * i <= n:
        while n % i == 0:
            factors.append(i)
            n //= i
        i += 1
    if n > 1:
        factors.append(n)
    return factors

n, k = map(int, input().split())

factors = prime_factors(n)

if len(factors) < k:
    print(-1)
else:
    result = [1] * k

    # Distribute prime factors
    idx = 0
    for i in range(k):
        # Multiply this prime factor to the current result element
        if idx < len(factors):
            result[i] *= factors[idx]
            idx += 1
        else:
            # We've distributed all prime factors, just keep it at 1
            break

    # If we still have prime factors left, we need to combine them
    while idx < len(factors):
        result[0] *= factors[idx]
        idx += 1

    print(' '.join(map(str, result)))
"}

