def solve():
    n = int(input())
    a = list(map(int, input().split()))
    b = list(map(int, input().split()))
    m = int(input())

    # Sort sequences by x-coordinate
    a.sort()
    b.sort()

    # dp[i][j] will store a dictionary of last_x -> count
    dp = [[dict() for _ in range(n + 1)] for _ in range(n + 1)]
    dp[0][0][None] = 1  # No elements taken, last_x is None

    for i in range(n + 1):
        for j in range(n + 1):
            if i + j == 0:
                continue

            # Consider taking the next element from sequence A
            if i > 0:
                last_x_dict = dp[i - 1][j]
                for last_x, cnt in last_x_dict.items():
                    if last_x is None or a[i - 1] >= last_x:
                        new_last_x = a[i - 1]
                        if new_last_x in dp[i][j]:
                            dp[i][j][new_last_x] = (dp[i][j][new_last_x] + cnt) % m
                        else:
                            dp[i][j][new_last_x] = cnt % m

            # Consider taking the next element from sequence B
            if j > 0:
                last_x_dict = dp[i][j - 1]
                for last_x, cnt in last_x_dict.items():
                    if last_x is None or b[j - 1] >= last_x:
                        new_last_x = b[j - 1]
                        if new_last_x in dp[i][j]:
                            dp[i][j][new_last_x] = (dp[i][j][new_last_x] + cnt) % m
                        else:
                            dp[i][j][new_last_x] = cnt % m

    # Sum all possibilities for taking n elements from each sequence
    result = 0
    for last_x, cnt in dp[n][n].items():
        result = (result + cnt) % m

    print(result)

solve()
