import sys
from functools import lru_cache

def solve(n):
    s = str(n)
    length = len(s)

    @lru_cache(maxsize=None)
    def dp(pos, tight, leading_zero):
        if pos == length:
            return 1 if not leading_zero else 0
        max_prod = 0
        upper = int(s[pos]) if tight else 9
        for d in range(upper + 1):
            new_tight = tight and (d == upper)
            new_leading_zero = leading_zero and (d == 0)
            if d == 0:
                # We can just skip (leading_zero remains True) or place 0 (leading_zero becomes False)
                # If we place 0 and leading_zero becomes False, product = 0
                new_prod = 0
            else:
                if leading_zero:
                    # First non-zero digit, product = d
                    new_prod = d
                else:
                    new_prod = d * dp(pos + 1, new_tight, False)
            if new_prod > max_prod:
                max_prod = new_prod
        return max_prod

    result = dp(0, True, True)
    return result

if __name__ == '__main__':
    n = int(sys.stdin.readline())
    print(solve(n))
"}

