import sys
import math

def solve():
    n = int(sys.stdin.readline())
    for _ in range(n):
        a, b = map(int, sys.stdin.readline().split())

        # a = P^2 * Q, b = P * Q^2
        # => P = a / Q, Q = b / P
        # => P * Q = gcd(a, b) = g
        # => P = g / B, Q = g / A where A = a/g, B = b/g
        g = math.gcd(a, b)

        # We need both a/g and b/g to divide g
        # So g must be divisible by both a/g and b/g
        if g % (a // g) == 0 and g % (b // g) == 0:
            # Check if the product of P and Q equals g
            p = g // (b // g)
            q = g // (a // g)
            if p * q == g:
                # Also check if a and b are not equal
                if a != b:
                    print("Yes")
                else:
                    print("No")
            else:
                print("No")
        else:
            print("No")

solve()
