def solve():
    n = int(sys.stdin.readline())
    for _ in range(n):
        a, b = map(int, sys.stdin.readline().split())
        product = a * b

        # Find the cube root of product
        # Use a binary search approach to find the cube root more reliably
        low, high = 1, 1000000000  # Since product <= 1e9 * 1e9 = 1e18, cube root <= 1e6
        cube_root = 1

        # Binary search for the cube root
        while low <= high:
            mid = (low + high) // 2
            cube = mid * mid * mid
            if cube == product:
                cube_root = mid
                break
            elif cube < product:
                low = mid + 1
            else:
                high = mid - 1

        if cube_root ** 3 != product:
            print("No")
        else:
            # Check if cube_root divides a and product
            if product % cube_root == 0 and cube_root % (a // cube_root) == 0:
                print("Yes")
            else:
                print("No")

solve()
