# Read the 9x9 grid
grid = []
for _ in range(9):
    line = input().strip().replace(' ', '')
    grid.append(list(line))

# Read the last move coordinates
x, y = map(int, input().split())
last_move = (x, y)

# Find which small field contains the last move
# Small fields are 3x3 grids, numbered from 0 to 8
last_move_small_field = None
for i in range(3):
    for j in range(3):
        # Top-left corner of this small field
        small_x_start = 1 + i * 3
        small_y_start = 1 + j * 3
        # Check if last_move is in this small field
        if (small_x_start <= x <= small_x_start + 2) and (small_y_start <= y <= small_y_start + 2):
            last_move_small_field = (i, j)
            break
    if last_move_small_field:
        break

# Check if the last move field has any empty cells
has_empty = False
for i in range(3):
    for j in range(3):
        # Coordinates in this small field
        field_x = 1 + i
        field_y = 1 + j
        # Check if this cell is in the last move field
        if (last_move_small_field[0] == i) and (last_move_small_field[1] == j):
            # This is a cell in the last move field
            if grid[i][j] == '.':
                has_empty = True
                break
    if has_empty:
        break

# Find available moves
available = []
if not has_empty:
    # Can move anywhere
    for i in range(9):
        for j in range(9):
            if grid[i][j] == '.':
                available.append((i+1, j+1))  # Convert to 1-indexed
else:
    # Can only move within the last move field
    for i in range(3):
        for j in range(3):
            if grid[i][j] == '.':
                # Convert to 1-indexed and record as available
                available.append((i+1, j+1))

# Mark available cells with '!', keep others as-is
result = [list(row) for row in grid]
for move_x, move_y in available:
    result[move_x - 1][move_y - 1] = '!' if not has_empty else '!

# Print result
for row in result:
    print(''.join(row))
"}

