def find_t(n, crush):

    # Find cycles in the graph
    visited = [False] * (n + 1)
    cycles = []

    for i in range(1, n + 1):
        if not visited[i]:
            current = i
            cycle = []
            while True:
                if visited[current]:
                    break
                visited[current] = True
                cycle.append(current)
                current = crush[current - 1]  # Crush array is 0-indexed

            # Handle self-loop
            if len(cycle) == 1:
                cycles.append(cycle)
            else:
                # Check if the cycle closes properly
                if cycle[-1] != crush[cycle[-1] - 1]:
                    # Not a cycle, handle as tree leading to a cycle
                    pass
                else:
                    cycles.append(cycle)

    # Find minimal t
    result = 1

    for cycle in cycles:
        c = len(cycle)
        if c == 1:
            # Self-loop, t must be 1
            if result != 1:
                result = 1
        else:
            # Find minimal t for cycle of length c
            # After 2 rounds with parameter t, we should return to the starting node
            # After 1 round: we move (t-1) steps
            # After 2 rounds: we move 2*(t-1) steps
            # Need 2*(t-1) ≡ 0 (mod c)

            # t-1 must be a multiple of c / gcd(2, c)
            factor = c // math.gcd(2, c)
            t = 1 + factor

            # Update result
            if result == 1:
                result = t
            else:
                result = lcm(result, t)

    return result

