import sys
import math
from math import gcd
from functools import reduce

def lcm(a, b):
    return a * b // gcd(a, b)

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    n = int(data[0])
    crush = list(map(int, data[1:1+n]))

    result = find_t(n, crush)
    print(result)

if __name__ == "__main__":
    main()
