def query_min(tree, node, start, end, l, r):
    if r < start or end < l:
        return float('inf')
    if l <= start and end <= r:
        return tree[node]
    mid = (start + end) // 2
    return min(query_min(tree, 2*node, start, mid, l, r),
              query_min(tree, 2*node+1, mid+1, end, l, r))

def update(tree, node, start, end, idx, value):
    if start == end:
        tree[node] = value
    else:
        mid = (start + end) // 2
        if idx <= mid:
            update(tree, 2*node, start, mid, idx, value)
        else:
            update(tree, 2*node+1, mid+1, end, idx, value)
        tree[node] = min(tree[2*node], tree[2*node+1])

n = int(input())
a = list(map(int, input().split()))
result = [-1] * n

tree_size = 1
while tree_size < n:
    tree_size *= 2
	ree = [float('inf')] * (2 * tree_size)

for i in range(n):
    update(tree, 1, 0, n-1, i, a[i])

for i in range(n-1, -1, -1):
    if i == n-1:
        # No walruses ahead
        result[i] = -1
    else:
        # Find rightmost j where a[j] < a[i]
        l = i + 1
        r = n - 1
        min_val = query_min(tree, 1, 0, n-1, l, r)
        if min_val >= a[i]:
            # No younger walrus ahead
            result[i] = -1
        else:
            # Find the rightmost position with value < a[i]
            # Binary search
            low = l
            high = r
            ans = -1
            while low <= high:
                mid = (low + high) // 2
                val = query_min(tree, 1, 0, n-1, mid, r)
                if val < a[i]:
                    ans = mid
                    low = mid + 1
                else:
                    high = mid - 1
            result[i] = ans - i - 1

for r in result:
    print(r, end=' ')
