import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:n+1]))
    b = list(map(int, data[n+1:2*n+1]))
    m = int(data[2*n+1])

    # dp[i][j]: number of ways to merge first i from a and first j from b
    # with non-decreasing x-coordinates

    dp = [[0] * (n + 1) for _ in range(n + 1)]

    # Base case: only points from a
    for i in range(1, n + 1):
        dp[i][0] = 1

    # Base case: only points from b
    for j in range(1, n + 1):
        dp[0][j] = 1

    # Fill the DP table
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if a[i-1] < b[j-1]:
                dp[i][j] = dp[i-1][j]
            elif b[j-1] < a[i-1]:
                dp[i][j] = dp[i][j-1]
            else:  # a[i-1] == b[j-1]
                dp[i][j] = (dp[i-1][j] + dp[i][j-1]) % m

    print(dp[n][n] % m)

if __name__ == "__main__":
    solve()
