import sys
from collections import defaultdict, deque

def has_cycle(graph, n):
    """Check if a directed graph has a cycle using Kahn's algorithm (topological sort)."""
    in_degree = [0] * (n + 1)
    for u in graph:
        for v in graph[u]:
            in_degree[v] += 1

    queue = deque()
    for i in range(1, n + 1):
        if in_degree[i] == 0:
            queue.append(i)

    count = 0
    while queue:
        u = queue.popleft()
        count += 1
        for v in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    return count != n

def find_cycle(graph, n):
    """Find a cycle in the directed graph using DFS. Returns a list of nodes in the cycle (or empty list if no cycle)."""
    visited = [False] * (n + 1)
    rec_stack = [False] * (n + 1)
    parent = {}  # To store parent for cycle reconstruction
    cycle_nodes = []

    def dfs(u):
        nonlocal cycle_nodes
        visited[u] = True
        rec_stack[u] = True

        for v in graph[u]:
            if not visited[v]:
                parent[v] = u
                if dfs(v):
                    return True
            elif rec_stack[v]:
                # Found a cycle
                # Reconstruct cycle
                current = u
                cycle = []
                while True:
                    cycle.append(current)
                    if current == v:
                        break
                    current = parent[current]
                cycle.append(v)  # Add the starting node of the cycle

                # Extract just the cycle (without the repeated start node)
                cycle = cycle[1:] + [v]
                cycle_nodes.extend(cycle)
                return True

        rec_stack[u] = False
        return False

    for i in range(1, n + 1):
        if not visited[i]:
            if dfs(i):
                return cycle_nodes

    return []

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    graph = defaultdict(list)
    edges = []

    for _ in range(m):
        u = int(next(it))
        v = int(next(it))
        graph[u].append(v)
        edges.append((u, v))

    # Check if graph has a cycle
    if not has_cycle(graph, n):
        # It's a DAG, color all with 1
        print(1)
        print(' '.join(['1'] * m))
        return

    # Graph has a cycle, need at least 2 colors
    # Find a cycle and color it alternately
    cycle_nodes = find_cycle(graph, n)
    if not cycle_nodes:
        print(2)
        print(' '.join(['1'] * m))
        return

    # Assign colors
    colors = ['1'] * m

    # Find the cycle as a list of edges
    # Start from the first node in the cycle
    current = cycle_nodes[0]
    next_node = None
    for neighbor in graph[current]:
        if neighbor == cycle_nodes[1]:
            next_node = neighbor
            break

    # Trace through the cycle to find edges
    cycle_edges = []
    u = current
    while True:
        for v in graph[u]:
            if v == next_node:
                cycle_edges.append((u, v))
                break
        if next_node == cycle_nodes[0]:
