import sys

def expand_ipv6_short(short):
    # Split by : to get blocks and check for ::
    parts = short.split(':')
    if '::' not in short:
        # No compression, expand each block
        full_blocks = []
        for block in parts:
            if not block:
                block = '0000'
            # Pad to 4 digits, ensuring it's exactly 4
            if len(block) == 4:
                full_blocks.append(block)
            else:
                # Add leading zeros
                full_blocks.append(block.zfill(4))
        return ':'.join(full_blocks)
    else:
        # Split the string on ::
        left_right = short.split('::')
        if len(left_right) != 2:
            return 'Invalid::'  # shouldn't happen per problem
        left = left_right[0].split(':') if left_right[0] else []
        right = left_right[1].split(':') if left_right[1] else []
        # Calculate number of missing zero blocks
        total_blocks = 8
        num_zero_blocks_needed = total_blocks - len(left) - len(right)
        if num_zero_blocks_needed < 0:
            return 'Too many blocks'  # shouldn't happen per problem
        # Expand blocks and pad
        full_blocks = []
        for block in left:
            if not block:
                block = '0000'
            full_blocks.append(block.zfill(4))
        for i in range(num_zero_blocks_needed):
            full_blocks.append('0000')
        for block in right:
            if not block:
                block = '0000'
            full_blocks.append(block.zfill(4))
        return ':'.join(full_blocks)

def main():
    input_lines = sys.stdin.read().strip().split('\n')
    n = int(input_lines[0])
    for line in input_lines[1:n+1]:
        result = expand_ipv6_short(line.strip())
        print(result)

if __name__ == '__main__':
    main()
