def watered_sections(start, heights):
    """Count how many sections can be watered starting from the given section"""
    n = len(heights)
    count = 1  # Start section itself

    # Flow to the left
    i = start - 1
    while i >= 0:
        if heights[i] <= heights[i+1]:
            count += 1
            i -= 1
        else:
            break

    # Flow to the right
    i = start + 1
    while i < n:
        if heights[i-1] >= heights[i]:
            count += 1
            i += 1
        else:
            break

    return count

n = int(input())
heights = list(map(int, input().split()))

max_watered = 0
for i in range(n):
    max_watered = max(max_watered, watered_sections(i, heights))

print(max_watered)
