def restore_ipv6(short):
    # Split by colons
    parts = short.split(':')

    # Check if :: exists
    if '::' in short:
        # Split into before and after
        before_parts, after_parts = short.split('::')

        # Split each part by colon
        before_parts = before_parts.split(':') if before_parts else []
        after_parts = after_parts.split(':') if after_parts else []

        # Count how many zero blocks we need
        num_blocks = 8
        num_existing = len(before_parts) + len(after_parts)
        num_zero_blocks = num_blocks - num_existing

        # Expand each part
        expanded = []
        for part in before_parts:
            if part == '0':
                expanded.append('0000')
            else:
                expanded.append(part.zfill(4))

        for _ in range(num_zero_blocks):
            expanded.append('0000')

        for part in after_parts:
            if part == '0':
                expanded.append('0000')
            else:
                expanded.append(part.zfill(4))

        return ':'.join(expanded)
    else:
        # No ::, just expand each part
        expanded = []
        for part in parts:
            if part == '0':
                expanded.append('0000')
            else:
                expanded.append(part.zfill(4))

        return ':'.join(expanded)

n = int(input())
for _ in range(n):
    short = input().strip()
    print(restore_ipv6(short))
