def is_white_winning(board):
    """Check if player A can win"""
    for r in range(1, 9):
        for c in range(1, 9):
            if board[r][c] == 'W':
                # Check if white pawn at (r, c) can reach row 1
                # Check if column c is empty in all rows from 1 to r-1
                if all(board[row][c] == '.' for row in range(1, r)):
                    return True
    return False


def is_black_winning(board):
    """Check if player B can win"""
    for r in range(1, 9):
        for c in range(1, 9):
            if board[r][c] == 'B':
                # Check if black pawn at (r, c) can reach row 8
                # Check if column c is empty in all rows from r+1 to 8
                if all(board[row][c] == '.' for row in range(r+1, 9)):
                    return True
    return False


def min_moves_white(board):
    """Find minimum moves for player A to win"""
    min_moves = float('inf')
    for r in range(1, 9):
        for c in range(1, 9):
            if board[r][c] == 'W':
                # Check if column c is empty in all rows from 1 to r-1
                if all(board[row][c] == '.' for row in range(1, r)):
                    # This white pawn can win in (r-1) moves
