    for r in range(1, 9):
        for c in range(1, 9):
            if board[r-1][c-1] == 'W':
                # Check if column c is empty in all rows from 1 to r-1
                if all(board[row][c-1] == '.' for row in range(r-1)):
                    return True
    return False


def is_black_winning(board):
    """Check if player B can win"""
    for r in range(1, 9):
        for c in range(1, 9):
            if board[r-1][c-1] == 'B':
                # Check if column c is empty in all rows from r+1 to 8
                if all(board[row][c-1] == '.' for row in range(r, 8)):
                    return True
    return False


def min_moves_white(board):
    """Find minimum moves for player A to win"""
    min_moves = float('inf')
    for r in range(1, 9):
        for c in range(1, 9):
            if board[r-1][c-1] == 'W':
                # Check if column c is empty in all rows from 1 to r-1
                if all(board[row][c-1] == '.' for row in range(r-1)):
                    # This white pawn can win in (r-1) moves
                    min_moves = min(min_moves, r-1)
    return min_moves


def min_moves_black(board):
    """Find minimum moves for player B to win"""
    min_moves = float('inf')
    for r in range(1, 9):
        for c in range(1, 9):
            if board[r-1][c-1] == 'B':
                # Check if column c is empty in all rows from r+1 to 8
                if all(board[row][c-1] == '.' for row in range(r, 8)):
                    # This black pawn can win in (8-r) moves
                    min_moves = min(min_moves, 8-r)
    return min_moves


# Read input
board = []
for _ in range(8):
    line = input().strip()
    board.append(list(line))

# Check who can win
a_can_win = is_white_winning(board)
b_can_win = is_black_winning(board)

# Determine winner
if a_can_win and not b_can_win:
    print('A')
elif b_can_win and not a_can_win:
    print('B')
elif a_can_win and b_can_win:
    a_moves = min_moves_white(board)
    b_moves = min_moves_black(board)
    if a_moves < b_moves:
        print('A')
    elif a_moves > b_moves:
        print('B')
    else:
        # If equal moves, player A wins because they go first
        print('A')
else:
    # According to problem statement, there will always be a winner
    # So this case shouldn't happen
    print('A')

