def solve():
    n, k = map(int, input().split())

    # Start with 1
    perm = [1]

    # Current position
    current = 1

    # We need k distinct differences
    # Create differences: k, k+1, k+2, ..., k+(k-1)

    for diff in range(k, k + k - 1):
        # Alternate between adding and subtracting differences
        if len(perm) % 2 == 1:
            # Odd length, subtract
            next_val = current - diff
        else:
            # Even length, add
            next_val = current + diff

        # Check if next_val is valid (within 1..n and not already used)
        if 1 <= next_val <= n and next_val not in perm:
            perm.append(next_val)
            current = next_val

    # If we haven't filled the permutation yet, just fill with remaining numbers
    while len(perm) < n:
        for i in range(2, n + 1):
            if i not in perm:
                perm.append(i)
                break

    print(' '.join(map(str, perm)))

