def solve():
    n, k = map(int, input().split())

    # Start with 1
    perm = [1]

    # Create the first k distinct differences
    for i in range(1, k + 1):
        if i % 2 == 1:
            # Odd index, add i
            perm.append(perm[-1] + i)
        else:
            # Even index, subtract i
            perm.append(perm[-1] - i)

    # Remove the last element (it might be out of bounds or duplicate)
    if len(perm) > 1 and perm[-1] < 1:
        perm.pop()

    # Fill in the rest of the permutation with remaining numbers
    used = set(perm)
    while len(perm) < n:
        for i in range(2, n + 1):
            if i not in used:
                perm.append(i)
                used.add(i)
                break

    print(' '.join(map(str, perm)))

