{"code": "
from collections import Counter

t = input().strip()
pieces = input().strip()

# Count occurrences of each digit in t
required = Counter()
for ch in t:
    required[ch] += 1

# Count occurrences of each digit in pieces
available = Counter()
for ch in pieces:
    available[ch] += 1

# Try to make as many instances as possible
instances = 0

while True:
    # Check if we can make one more instance
    can_make = True

    for ch, count in required.items():
        # We need 'count' of digit 'ch'
        # Try to use available ch or swapped version

        if ch == '2' or ch == '5':
            # We can use ch or the other one (5/2)
            if available[ch] > 0:
                available[ch] -= 1
            else:
                if available[('5' if ch == '2' else '2')] > 0:
                    available[('5' if ch == '2' else '2')] -= 1
                else:
                    can_make = False
                    break
        elif ch == '6' or ch == '9':
            # We can use ch or the other one (9/6)
            if available[ch] > 0:
                available[ch] -= 1
            else:
                if available[('9' if ch == '6' else '6')] > 0:
                    available[('9' if ch == '6' else '6')] -= 1
                else:
                    can_make = False
                    break
        else:
            # Must use exact match
            if available[ch] > 0:
                available[ch] -= 1
            else:
                can_make = False
                break

    if can_make:
        instances += 1
    else:
        break

print(instances)
