k, d = map(int, input().split())

if d == 0:
    if k == 1:
        print("0")
    else:
        print("No solution")
else:
    # Try sums: d, d+9, d+18, d+27
    for s in [d, d+9, d+18, d+27]:
        if s <= 9 * k and s >= k:
            # Construct a k-digit number with sum of digits s
            # Place the sum as the first digit if possible
            if s <= 9:
                result = str(s) + '0' * (k - 1)
                print(result)
                exit()
            else:
                # Distribute the sum: one digit is s % 9, others are s // 9
                first = s % 9
                rest = s // 9
                # Ensure first digit is at least 1
                if first == 0:
                    first = rest
                    rest -= 1
                result = str(first) + str(rest) * (k - 1)
                print(result)
                exit()
    print("No solution")
"}

