n = int(input())
a = list(map(int, input().split()))

# We'll store the furthest younger walrus index for each position
furthest_younger = [-1] * n

tail = n - 1  # Start from the end of the queue (head of the queue)
for i in range(n - 1, -1, -1):
    # Find the furthest younger walrus ahead
    # We'll look from the current furthest index onwards
    if furthest_younger[i + 1] != -1:
        j = furthest_younger[i + 1]
        # Check if there's a younger walrus between j and tail
        while j < tail and a[j] >= a[i]:
            j = furthest_younger[j + 1]
        if j < tail:
            furthest_younger[i] = j
        else:
            furthest_younger[i] = -1
    else:
        # No younger walrus ahead of i+1, check from i+1 to tail
        j = i + 1
        while j < tail and a[j] >= a[i]:
            j = furthest_younger[j + 1]
        if j < tail:
            furthest_younger[i] = j
        else:
            furthest_younger[i] = -1

# Calculate displeasure
output = []
for i in range(n):
    if furthest_younger[i] != -1:
        output.append(str(furthest_younger[i] - i - 1))
    else:
        output.append("-1")

print(" ".join(output))
