    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    # If all parts have the same height, we're done
    if len(set(a)) == 1:
        print("YES")
        return

    # If all elements have the same parity, we can always complete the wall
    min_h = min(a)
    parity = min_h % 2
    all_same_parity = all((h - min_h) % 2 == parity for h in a)
    if all_same_parity:
        print("YES")
        return

    # If the minimum height is 0, we can always complete
    if min_h == 0:
        print("YES")
        return

    # If we have adjacent parts with the same height, we can start increasing
    has_adjacent_same = False
    for i in range(n - 1):
        if a[i] == a[i + 1]:
            has_adjacent_same = True
            break

    if has_adjacent_same:
        print("YES")
    else:
        print("NO")

if __name__ == "__main__":
