    for _ in range(t):
        n = int(input())
        a = list(map(int, input().split()))

        if n == 1:
            # Single element, already equal
            print(0)
            continue

        res = []

        # Use index 0 as the base
        for i in range(1, n):
            delta = a[i] - a[0]

            if delta > 0:
                # Need to decrease a[i], take from i to 0
                x = delta // n
                if delta % n != 0:
                    x += 1
                res.append((i+1, 1, x))  # Convert to 1-indexed
