            if board[r][c] == 'W':
                white_positions.append((r, c))
            elif board[r][c] == 'B':
                black_positions.append((r, c))

    # Check if white can win
    white_wins = False
    for w_r, w_c in white_positions:
        # White pawn at (w_r, w_c) needs w_r moves to reach row 1 (from row w_r to row 1 is w_r-1 moves)
        # Actually, from row w_r to row 1 is w_r-1 moves
        white_moves_needed = w_r - 1

        # Check if there's a black pawn in the same column that can block it
        black_blocking = False
        for b_r, b_c in black_positions:
            if b_c == w_c and b_r > w_r:  # Black pawn in same column and below white pawn
                # Black pawn at (b_r, b_c) needs b_r - w_r moves to reach row w_r
                # If black can reach row w_r before white can reach row 1, it blocks
                if b_r - w_r < white_moves_needed:
                    black_blocking = True
                    break

        if not black_blocking:
            white_wins = True
            break

    # Check if black can win
    black_wins = False
    for b_r, b_c in black_positions:
        # Black pawn at (b_r, b_c) needs 8 - b_r moves to reach row 8
        black_moves_needed = 8 - b_r

        # Check if there's a white pawn in the same column that can block it
        white_blocking = False
        for w_r, w_c in white_positions:
            if w_c == b_c and w_r < b_r:  # White pawn in same column and above black pawn
                # White pawn at (w_r, w_c) needs b_r - w_r moves to reach row b_r
                # If white can reach row b_r before black can reach row 8, it blocks
                if b_r - w_r < black_moves_needed:
                    white_blocking = True
                    break

        if not white_blocking:
            black_wins = True
            break

    # If both can win, the one with fewer total moves wins
    if white_wins and black_wins:
        white_total = min([w_r - 1 for w_r, w_c in white_positions])
        black_total = min([8 - b_r for b_r, b_c in black_positions])
        if white_total <= black_total:
            print('A')
        else:
            print('B')
    elif white_wins:
        print('A')
    else:
        print('B')

if __name__ == '__main__':
