import sys
from collections import defaultdict, deque

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    computers = [0] + [int(next(it)) for _ in range(n)]  # 1-indexed

    # Parse dependencies
    dependencies = defaultdict(list)
    for part in range(1, n + 1):
        ki = int(next(it))
        for dep in range(ki):
            dependencies[part].append(int(next(it)))

    # Check if a part can be completed given current mask
    def can_complete(part: int, mask: int) -> bool:
        for dep in dependencies[part]:
            if not (mask & (1 << (dep - 1))):
                return False
        return True

    # Cost matrix for moving between computers
    cost = {
        (1, 2): 1,
        (1, 3): 2,
        (2, 1): 2,
        (2, 3): 1,
        (3, 1): 1,
        (3, 2): 2
    }

    # BFS with bitmask state (mask, computer)
    from collections import deque

    # Priority queue: (time, mask, computer)
    pq = [(0, 0, c) for c in range(1, 4)]
    visited = {(0, c): 0 for c in range(1, 4)}

    while pq:
        time, mask, computer = heapq.heappop(pq)

        # Try completing any part that can be completed
        for part in range(1, n + 1):
            if can_complete(part, mask):
                new_mask = mask | (1 << (part - 1))

                # Calculate time to complete this part
                if computer == computers[part]:
                    new_time = time + 1
                else:
                    # Need to move to the correct computer
                    move_time = cost.get((computer, computers[part]), 0)
                    new_time = time + move_time + 1

                # Check if we've reached all parts
                if new_mask == (1 << n) - 1:
                    print(new_time)
                    return

                if (new_mask, computers[part]) not in visited or new_time < visited[(new_mask, computers[part])]:
                    visited[(new_mask, computers[part])] = new_time
                    heapq.heappush(pq, (new_time, new_mask, computers[part]))

    print(-1)

if __name__ == "__main__":
    solve()
