import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    data = [int(x) for x in data]
    n = data[0]
    m = data[1]
    a = []
    idx = 2

    for i in range(n):
        row = data[idx:idx+m]
        a.append(row)
        idx += m

    # For each intersection (i, j):
    # - Consider row i and column j
    # - Sort while preserving relative order
    # - The answer is the number of unique elements

    result = [[0] * m for _ in range(n)]

    for i in range(n):
        for j in range(m):
            # Collect all values in row i and column j, except a[i][j]
            values = []

            # Row i
            for k in range(m):
                values.append((a[i][k], i, k))  # (value, row, col)

            # Column j
            for k in range(n):
                if k != i:
                    values.append((a[k][j], k, j))

            # Sort by value, then by row, then by column
            values.sort(key=lambda x: (x[0], x[1], x[2]))

            # Assign ranks
            rank = {}
            for val, row, col in values:
                if val not in rank:
                    rank[val] = 0
                rank[val] += 1

            # The answer is the number of unique values
            result[i][j] = len(rank)

