# Union-Find data structure for rows
parent = {}

def find(x):
    if parent[x] != x:
        parent[x] = find(parent[x])
    return parent[x]

def union(x, y):
    if x not in parent:
        parent[x] = x
    if y not in parent:
        parent[y] = y

    px = find(x)
    py = find(y)

    if px != py:
        parent[px] = py

# Initialize union-find for all rows that have elements
for c in column_rows:
    for r in column_rows[c]:
        if r not in parent:
            parent[r] = r
        # Connect all rows in this column
        for other_r in column_rows[c]:
            if other_r != r:
                union(r, other_r)

# Count number of free columns (columns with exactly one element)
free_columns = 0
for c in column_rows:
    if len(column_rows[c]) == 1:
        free_columns += 1

# Count number of connected components
if n == 1:
    # In one row, we can't do fusion, just buy missing elements
    # Number of missing elements = (m - free_columns)
    print(m - free_columns)
else:
    # In multiple rows, we need to consider connected components
    # Number of connected components = (number of rows) - (number of unions)
    # We need at least (number of rows - 1) to span all rows
    # But we already have free_columns elements
    # So answer = m - free_columns - (n - 1)
    print(m - free_columns - (n - 1))
