def solve():
    n = int(input())
    computer = list(map(int, input().split()))

    # Build adjacency list
    graph = [[] for _ in range(n + 1)]
    for i in range(1, n + 1):
        parts = list(map(int, input().split()))
        k = parts[0]
        if k > 0:
            for j in parts[1:]:
                graph[j].append(i)  # j is prerequisite for i

    # Topological sort (post-order)
    visited = [False] * (n + 1)
    order = []

    def dfs(v):
        visited[v] = True
        for neighbor in graph[v]:
            if not visited[neighbor]:
                dfs(neighbor)
        order.append(v)

    for i in range(1, n + 1):
        if not visited[i]:
            dfs(i)

    # DP: dp[i][c] = minimum time to process all parts with dependencies starting at computer c
    dp = [[float('inf')] * 4 for _ in range(n + 1)]  # 4 for 1-indexing

    # Base case: no dependencies
    for i in range(1, n + 1):
        dp[i][computer[i - 1]] = 1

    # Process in reverse topological order
    for i in reversed(order):
        current_comp = computer[i - 1]

        # Case: start at computer 1
        time_1 = dp[i][current_comp]
        dp[i][1] = time_1

        # Case: start at computer 2
        time_2 = dp[i][current_comp]
        dp[i][2] = time_2

        # Case: start at computer 3
        time_3 = dp[i][current_comp]
        dp[i][3] = time_3

        # Actually, we need to consider movement from starting computer to current computer
        # and then recursive processing

        # Let me think differently

        # For each possible starting computer, calculate the minimum time
        for start in range(1, 4):
            if start == current_comp:
                # Already at the right computer
                time = 1 + min(dp[neighbor][current_comp] for neighbor in graph[i])
            else:
                # Need to move first
