def solve():
    n = int(input())
    computer = list(map(int, input().split()))

    # Build adjacency list (prerequisites -> dependents)
    graph = [[] for _ in range(n)]
    for i in range(n):
        parts = list(map(int, input().split()))
        k = parts[0]
        if k > 0:
            for j in parts[1:]:
                graph[j - 1].append(i)  # j is prerequisite for i (1-indexed to 0-indexed)

    # Post-order traversal (prerequisites first)
    visited = [False] * n
    order = []

    def dfs(v):
        visited[v] = True
        for neighbor in graph[v]:
            if not visited[neighbor]:
                dfs(neighbor)
        order.append(v)

    for i in range(n):
        if not visited[i]:
            dfs(i)

    # DP: dp[i][c] = minimum time to process all parts that depend on part i, starting from computer c
    dp = [[float('inf')] * 4 for _ in range(n)]  # 4 for computers 1,2,3

    # Base case: no dependencies
    for i in range(n):
        dp[i][computer[i]] = 1

    # Process in post-order (prerequisites first)
    for i in reversed(order):
        current_comp = computer[i]

        for start in range(1, 4):
            # Time to move from starting computer to current computer
            move_time = 0
            if start == 1:
                if current_comp == 2:
                    move_time = 1
                elif current_comp == 3:
                    move_time = 2
            elif start == 2:
                if current_comp == 1:
                    move_time = 2
                elif current_comp == 3:
                    move_time = 1
            elif start == 3:
                if current_comp == 1:
                    move_time = 1
                elif current_comp == 2:
                    move_time = 2

            # Process part i
            # Then process all parts that depend on i from current computer

            # For each dependent part, we need to start at current computer
            min_dependent_time = 0
            for neighbor in graph[i]:
                min_dependent_time = max(min_dependent_time, dp[neighbor][current_comp])

            dp[i][start] = move_time + 1 + min_dependent_time

    # Initial position can be any computer
    answer = min(dp[0][1], dp[0][2], dp[0][3])
    print(answer)

solve()

