import sys
import math

def is_perfect_cube(x):
    if x < 0:
        return False
    cube_root = round(x ** (1/3))
    # Check if cube_root^3 == x
    # Also check nearby integers due to floating point precision
    for i in range(cube_root - 2, cube_root + 3):
        if i ** 3 == x:
            return True
    return False

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    index = 1
    output = []

    for _ in range(n):
        a = int(data[index])
        b = int(data[index + 1])
        index += 2

        product = a * b
        if product == 0:
            # Not possible, both scores start at 1
            output.append("No")
            continue

        if is_perfect_cube(product):
            output.append("Yes")
        else:
            output.append("No")

    sys.stdout.write("\n".join(output))

if __name__ == "__main__":
    main()
