def solve():
    MOD = 10**9 + 7

    N, L, M = map(int, input().split())

    # E: entry to first layer
    E = list(map(int, input().split()))
    # C: cost between adjacent layers (transition matrix)
    C = list(map(int, input().split()))
    # X: last layer to exit
    X = list(map(int, input().split()))

    # Compute cost to each city in the next layer (C[0][j])
    cost_to_j = [c % M for c in C]
    cnt = [0] * M
    for c in cost_to_j:
        cnt[c] += 1

    # Start frequencies: how many cities have remainder r after entry
    start = [0] * M
    for e in E:
        start[e % M] += 1

    # End frequencies: how many cities have remainder r before exit
    end = [0] * M
    for x in X:
        end[x % M] += 1

    # Transition matrix: from remainder r, how many ways to get to remainder s in 1 step
    P1 = [[0] * M for _ in range(M)]
    for r in range(M):
        for c in range(M):
            if cnt[c] > 0:
                s = (r + c) % M
                P1[r][s] += cnt[c]
                P1[r][s] %= MOD

    # Matrix exponentiation: compute P[L-1]
    def multiply(A, B):
        res = [[0] * M for _ in range(M)]
        for i in range(M):
            for k in range(M):
                if A[i][k] == 0:
                    continue
                for j in range(M):
                    res[i][j] = (res[i][j] + A[i][k] * B[k][j]) % MOD
        return res

    def matrix_pow(mat, power):
        result = [[1 if i == j else 0 for j in range(M)] for i in range(M)]
        while power > 0:
            if power % 2 == 1:
                result = multiply(result, mat)
            mat = multiply(mat, mat)
            power //= 2
        return result

    P = matrix_pow(P1, L - 1)

    answer = 0
    for r_start in range(M):
        for r_exit in range(M):
            target = (- (r_start + r_exit)) % M
            ways = P[r_start][target]  # number of ways from r_start to target in L-1 transitions
            answer = (answer + start[r_start] * end[r_exit] * ways) % MOD

    print(answer)

solve()
