def max_product_of_digits(n):

    # Convert to string
    s = str(n)
    digits = [int(c) for c in s]
    length = len(digits)

    # If the first digit is 1 and the rest are 0s, we can't form a number with all 9s
    if digits[0] == 1 and all(d == 0 for d in digits[1:]):
        return 9 ** (length - 1)

    # Try to find the rightmost digit that is not 1
    for i in range(length - 1, -1, -1):
        if digits[i] != 1:
            # Replace this digit with 9 and set all following digits to 9
            digits[i] = 9
            for j in range(i + 1, length):
                digits[j] = 9
            # Calculate the product of the resulting number's digits
            product = 1
            for d in digits:
                product *= d
            return product

    # If all digits are 1, we can't improve the product
    return 9 ** length

