    n = int(sys.stdin.readline())
    out_lines = []

    for _ in range(n):
        a, b = map(int, sys.stdin.readline().split())

        # Check if a * b is a perfect cube
        # We'll use binary search for efficiency
        low, high = 1, 10**9
        while low < high:
            mid = (low + high) // 2
            if mid ** 3 < a * b:
                low = mid + 1
            else:
                high = mid
        cube_root = low

        # Check if cube_root^3 == a * b
        if cube_root ** 3 != a * b:
            out_lines.append("No")
            continue

        # Now check if we can find integers p and q such that a = p * q² and b = q * p²
        # Since a * b = (p * q)^3, p * q = cube_root
        # And a / b = p / q

        # Try all possible values for q up to cube_root
        found = False

