def solve():
    n, k = map(int, input().split())

    # If k >= n, use a simple repeating pattern
    if k >= n:
        result = ''.join(chr(ord('a') + i) for i in range(n))
    else:
        # Use a greedy approach to build a string with unique adjacent pairs
        # Start with the first character
        s = [chr(ord('a'))]
        used_pairs = set()

        for i in range(1, n):
            # Try each possible character
            for c in range(ord('a'), ord('a') + k):
                pair = (s[-1], chr(c))
                if pair not in used_pairs:
                    s.append(chr(c))
                    used_pairs.add(pair)
                    break

    print(''.join(s))

solve()
